using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;public static class GraphicsProbe{public static string Run(){var p=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;return $"pipeline={p.name}; scale={p.renderScale}; msaa={p.msaaSampleCount}; shadows={p.shadowDistance}; screen={Screen.width}x{Screen.height}; vSync={QualitySettings.vSyncCount}; target={Application.targetFrameRate}";}}
